fn stored_rows(corpus: &Value) -> Vec<StoredExceptionRow> {
    corpus["rows"]
        .as_array()
        .expect("rows")
        .iter()
        .map(|row| StoredExceptionRow {
            target_type: row["target_type"].as_str().map(str::to_owned),
            target_id: row["target_id"].as_str().map(str::to_owned),
            original_start_local: row["original_start_local"].as_str().map(str::to_owned),
            recurrence_semantics: row["recurrence_semantics"].as_str().map(str::to_owned),
            scope: row["scope"].as_str().map(str::to_owned),
            action: row["action"].as_str().map(str::to_owned),
            override_json: row["override_json"].as_str().map(str::to_owned),
        })
        .collect()
}

#[test]
fn the_occurrence_column_is_spelled_once_and_v0_agrees() {
    let corpus = fixture("occurrence-cases.json");
    assert_eq!(
        occurrence::OCCURRENCE_LOCAL_START_COLUMN,
        text(&corpus, "column")
    );
}

#[test]
fn every_stored_exception_reads_as_v0_reads_it() {
    let corpus = fixture("occurrence-cases.json");
    let rows = stored_rows(&corpus);
    let found = occurrence::exceptions_of(&rows, SeriesType::Event, "event-1");
    let expected = corpus["exceptions"].as_array().expect("exceptions");
    assert_eq!(
        found.len(),
        expected.len(),
        "a row with no key is not an exception"
    );
    for (exception, want) in found.iter().zip(expected) {
        let label = text(want, "localStart");
        assert_eq!(exception.key.local_start, label, "local start");
        assert_eq!(
            exception.key.series_type.as_str(),
            text(want, "seriesType"),
            "{label}: series type"
        );
        assert_eq!(
            exception.key.semantics.as_str(),
            text(want, "semantics"),
            "{label}: semantics"
        );
        assert_eq!(exception.key.token(), text(want, "token"), "{label}: token");
        let action = match exception.action {
            ExceptionAction::Skip => "skip",
            ExceptionAction::Override => "override",
        };
        assert_eq!(action, text(want, "action"), "{label}: action");
        let scope = match exception.scope {
            ExceptionScope::Occurrence => "occurrence",
            ExceptionScope::Future => "future",
        };
        assert_eq!(scope, text(want, "scope"), "{label}: scope");
        assert_eq!(
            exception.override_value.as_ref(),
            want["override"].as_object().map(|_| &want["override"]),
            "{label}: override"
        );
    }
}

#[test]
fn every_override_lookup_agrees_with_v0() {
    let corpus = fixture("occurrence-cases.json");
    let rows = stored_rows(&corpus);
    let exceptions = occurrence::exceptions_of(&rows, SeriesType::Event, "event-1");
    for case in corpus["overrideAt"].as_array().expect("overrideAt") {
        let at = text(case, "localStart");
        let found = occurrence::override_at(&exceptions, &at);
        let want = &case["override"];
        if want.is_null() {
            assert!(found.is_none(), "{at}: v0 found no override");
        } else {
            assert_eq!(found, Some(want), "{at}: override");
        }
    }
}

#[test]
fn the_exception_fold_agrees_with_v0_before_and_after() {
    let corpus = fixture("occurrence-cases.json");
    let expansion = &corpus["expansion"];
    let zone = FireZone::named(&text(expansion, "zone")).expect("a real zone");
    let rrule_text = text(expansion, "rrule");
    let start = text(expansion, "start");
    let from = text(expansion, "rangeFrom");
    let to = text(expansion, "rangeTo");
    let instances = recurrence::expand(
        &ExpandInput::new(&rrule_text, &start, &from, &to)
            .in_zone(&zone)
            .at_most(400),
    );
    let before = expansion["before"].as_array().expect("before");
    assert_eq!(instances.len(), before.len());
    for (occurrence, want) in instances.iter().zip(before) {
        assert_eq!(occurrence.wall_start, text(want, "wallStart"));
        assert_eq!(occurrence.start, text(want, "start"));
    }
    let rows = stored_rows(&corpus);
    let exceptions = occurrence::exceptions_of(&rows, SeriesType::Event, "event-1");
    let applied = recurrence::apply_exceptions(
        &instances,
        &occurrence::recurrence_exceptions_of(&exceptions),
    );
    let after = expansion["after"].as_array().expect("after");
    assert_eq!(applied.len(), after.len(), "the skip removed exactly one");
    for (occurrence, want) in applied.iter().zip(after) {
        assert_eq!(occurrence.wall_start, text(want, "wallStart"));
        assert_eq!(
            occurrence.start,
            text(want, "start"),
            "the override moved it"
        );
    }
}

/// ONT-25, held as a test rather than a paragraph.
#[test]
fn a_skip_keyed_on_the_resolved_instant_still_matches_nothing() {
    let corpus = fixture("occurrence-cases.json");
    let ont25 = &corpus["ont25"];
    let expansion = &corpus["expansion"];
    let zone = FireZone::named(&text(expansion, "zone")).expect("a real zone");
    let rrule_text = text(expansion, "rrule");
    let start = text(expansion, "start");
    let from = text(expansion, "rangeFrom");
    let to = text(expansion, "rangeTo");
    let instances = recurrence::expand(
        &ExpandInput::new(&rrule_text, &start, &from, &to)
            .in_zone(&zone)
            .at_most(400),
    );
    let wrong = recurrence::apply_exceptions(
        &instances,
        &[recurrence::RecurrenceException {
            original_start: text(ont25, "instantKey"),
            action: ExceptionAction::Skip,
            scope: ExceptionScope::Occurrence,
            start: None,
        }],
    );
    assert_eq!(
        wrong.len(),
        usize::try_from(ont25["keptWithInstantKey"].as_u64().unwrap_or_default())
            .unwrap_or_default(),
        "the instant key matches nothing, exactly as v0 says"
    );
    let right = recurrence::apply_exceptions(
        &instances,
        &[recurrence::RecurrenceException {
            original_start: text(ont25, "wallKey"),
            action: ExceptionAction::Skip,
            scope: ExceptionScope::Occurrence,
            start: None,
        }],
    );
    assert_eq!(right.len(), instances.len() - 1, "the wall key matches one");
}

#[test]
fn every_search_window_agrees_with_v0() {
    let corpus = fixture("occurrence-cases.json");
    for case in corpus["searchWindows"].as_array().expect("searchWindows") {
        let at = text(case, "localStart");
        let found = occurrence::search_window(&at, occurrence::SEARCH_WINDOW_DAYS);
        let want = &case["window"];
        if want.is_null() {
            assert!(found.is_none(), "{at}: v0 found no window");
        } else {
            let (from, to) = found.unwrap_or_else(|| panic!("{at}: this build found none"));
            assert_eq!(from, text(want, "from"), "{at}: from");
            assert_eq!(to, text(want, "to"), "{at}: to");
        }
    }
}

